## <mark>活动的选择</mark>

知识点：贪心，区间衔接，sort排序

题目：

![活动的选择](image/例题/屏幕截图%202025-11-11%20091202.png)

解法：

```c++
#include <bits/stdc++.h>
using namespace std;
struct timeq{
    int begin;
    int end;
};
int main(){
    int n;
    cin>>n;
    vector<timeq> activ(n);
    for(int i = 0;i<n;i++){
        cin>>activ[i].begin>>activ[i].end;
    }
    for(int i = 0;i<n-1;i++){
        for(int j = 0;j<n-1-i;j++){
            if(activ[j].end>activ[j+1].end){
                swap(activ[j],activ[j+1]);//按结束时间从早到晚排序，结束越早的排前面，最后能够排更多个数
            }
        }
    }
    int cnt = 1;
    for(int i = 0;i<n;){
        int j = i+1;
        while(j<n && activ[i].end>activ[j].begin){//从第一个最早结束的活动开始，向后寻找第一个匹配的活动
            j++;
        }
        //此刻在while结束后找到了一个j
        if(j<=n-1){
            cnt++;
            i = j;
        }else{
            break;//若j已经超出活动数量n，直接结束就可以了
        }
    }
    cout<<cnt;
    return 0;
}
```

