    string password;//比如密码私有
public://以下内容公开，class内外都可以调用和访问
    int age;
    string name;//属性，数据
    void print(){//普通函数
        cout<<age<<" "<<name<<endl;//用于做具体操作
    }
    类名称(int nianling,string xingming){//构造函数
        //函数名称必须与类名称一样，不需要写返还的类型
