        age = nianling;
        name = xingming;
    }
    类名称(){
        age = 0;
        name = "";
    }
};//别漏分号


int main(){
    //Class的类名称即是一个自定义的变量类型
    //可以自行在main中调用
    类名称 pastman;//无构造函数的初始化
    pastman.age = 18;
    pastman.name = "hth";
    //调用构造函数创建对象
    类名称 deadman(18,"hth");
    //利用class创建了一个自定义类型的变量，同时调用构造函数进行了初始化
    return 0;
}
```

