<mark>尾插入法：</mark>

```c++
#include<bits/stdc++.h>
using namespace std;
struct node{
    int data;
    node *next;
}
node *createlist(){
    node *head = new node();//创建头结点
    head->next = NULL;
    node *tail = head;//需要再创建一个尾结点
    while(1){
        int value;
        cin>>value;
        if(value<=0)break;
        node *newnode = new node();
        newnode->data = value;//老样子先处理数据
        tail->next = newnode;//处理newnode的尾
        tail = newnode;//移动到newnode上
        tail->next = NULL;//处理newnode的头
    }
    return head;
}
```

