#include <bits/stdc++.h>
using namespace std;
double f(double x, int n, int m) {//基本的递归写法，常看常新哦
    double result = sqrt(m + x);
    if (m < n) {
        return f(result, n, m + 1);
    } else {
        return result;
    }
}
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        double x;
        int n;
        scanf("%lf %d", &x, &n);
        double result = f(x, n, 1);//每次从m=1开始
        printf("%.3f\n", result);
    }
    return 0;
}
