int main(){
    string s1,s2;
    getline(cin,s1);
    getline(cin,s2);
    int len1 = s1.size();
    int len2 = s2.size();
    //dp[i][j]表示以s1[i-1]和s2[j-1]结尾的两个字串的最长公共子串长度
    vector<vector<int>> dp(len1+1,vector<int>(len2+1,0));
    int maxlen = 0;
    int endpos = 0;
    for(int i = 1;i<=len1;i++){
        for(int j = 1;j<=len2;j++){
            if(s1[i-1]==s2[j-1]){
                dp[i][j] = dp[i-1][j-1]+1;
                if(dp[i][j]>maxlen){
                    maxlen = dp[i][j];
                    endpos = i-1;
                }
            }else{
                dp[i][j] = 0;
            }
        }
    }
    cout<<maxlen<<endl;
    if(maxlen>0){
        string result = s1.substr(endpos-maxlen+1,maxlen);
        //至于为什么是endpos-maxlen+1
        //实在理解不了就举个例子，以个别情况推出一般情况
        cout<<result<<endl;
    }else{
        cout<<""<<endl;
    }
    return 0;
}
```

