## <mark>二分+贪心(最小的最大区间)</mark>

![杰哥的难题2](image/例题/屏幕截图%202025-12-15%20202642.png)

**策略：贪心+二分**

在一定范围内二分尝试各个最大的连续区间和，判断是否能够达到该最大区间和，

不断向更小的最大区间和二分尝试

 bool check:

若在当前要判断的mid值下，最少需要的分段数小于等于给定的分段数，就代表能够满足条件

```c++
#include<bits/stdc++.h>
using namespace std;
bool check(int mid,const vector<int>& cost,int n,int m){//数组使用&避免复制造成的浪费
    int cnt = 1;//至少分成一段
    int sum = 0;
    for(int i = 0;i<n;i++){
        if(cost[i]>mid){
            return false;
        }
        if(sum+cost[i]>mid){
            sum = cost[i];//重新开始累加,注意这里别写成"sum = 0"
            cnt++;//所需最少分段数+1
            if(cnt>m){
                return false;
            }
        }else{
            sum+=cost[i];
        }
    }
    return true;
}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int n,m;
    while(cin>>n>>m){
        vector<int> cost(n);
        int sum = 0;int maxc = 0;
        for(int i = 0;i<n;i++){
            cin>>cost[i];
            maxc = max(maxc,cost[i]);
            sum+=cost[i];
        }
        int l = maxc;
        int r = sum;
        int result = 0;
        while(l<=r){
            int mid = (l+r)/2;//令最大连续区间和为mid，判断是否可行
            //可以写成"mid = l+(r-l)/2"防止溢出
            if(check(mid,cost,n,m)){
                result = mid;
                r = mid-1;//向更小的最大区间和二分判断
            }else{
                l = mid+1;
            }
        }
        cout<<result<<'\n';
    }
    return 0;
}
```

